package com.logan.formstrength;
import android.app.Activity;
import android.os.Bundle;
import android.widget.*;
/** Required Health Connect permission-usage screen. No bridge and no network. */
public final class HealthPrivacyActivity extends Activity {
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(40,50,40,50);scroll.addView(box);TextView text=new TextView(this);text.setTextSize(17);text.setText("Form & Strength · Health data\n\nWe request read access to active calories burned, total calories burned, steps, distance and sleep session duration. We sync foreground data when the app opens/resumes or the selected date changes, no more frequently than every five minutes unless you tap Sync. Your band app must write these data types to Health Connect.\n\nDevice readings are displayed separately from manual activity estimates and food. Total calories include resting energy. We never add device calories to manual estimates or treat the difference as a prescribed diet target.\n\nNo Health Connect readings are sent to Gemini, our servers or advertisers. Aggregated readings are cached in private local SQLite storage with their date, time zone, source labels, timestamp and missing/error states. They are not included in exported backups. Revoking a metric clears its cached values when the app next checks access. Clear cached readings in Move → Device. We request no write, heart-rate, route, background or historical-extension permissions.\n\nYou can remove read permissions in Android Settings → Health Connect → App permissions. Disconnecting stops future reads; your separately logged manual records are unchanged. Only manual activities you mark as missing from device data are added to the synced burn baseline. Total burn takes priority; active burn is used only when total is unavailable and is labelled separately.\n\nOptional Gemini meal estimates send only the meal text you approve to Google's Gemini API. They do not send Health Connect data, weight or your diary. Gemini uses your own API project and its terms and quotas.\n\nYour food, check-in, activity and profile records live in private on-device storage. Uninstalling deletes them. Export backups before changing phones.");box.addView(text);Button close=new Button(this);close.setText("Close");close.setOnClickListener(v->finish());box.addView(close);setContentView(scroll);}
}
